mapper.select:
select count(hs.seq) from hospital_service hs join account ac on ac.seq = hs.account_seq and ac.is_enabled
hs.is_enabled
AND hs.hospital_seq = #{hospitalSeq}

select hs.seq as serviceSeq, ac.name, ac.seq as accountSeq, ch.seq as hospitalSeq, ch.name as hospitalName, CASE WHEN EXISTS ( SELECT 1 FROM account_disease ad WHERE ad.service_seq = hs.seq AND ad.is_enabled ) THEN 'APPROVE' ELSE 'REQUEST' END as status, ( SELECT to_char(min(ad.created_at) at time zone 'kst', 'YYYY-MM-DD HH24:MI:SS') FROM account_disease ad WHERE ad.service_seq = hs.seq AND ad.is_enabled ) as approveDate, to_char(cast(hs.created_at at time zone 'kst' AS timestamp), 'YYYY-MM-DD HH24:MI:SS') as createdAt from hospital_service hs join cm_hospital ch on ch.seq = hs.hospital_seq and ch.is_enabled join account ac on ac.seq = hs.account_seq and ac.is_enabled
hs.is_enabled
AND hs.hospital_seq = #{hospitalSeq}
ORDER BY hs.seq DESC
LIMIT #{pagination.endNum} OFFSET #{pagination.startNum}

select hs.seq as serviceSeq, ac.name, ac.seq as accountSeq, ch.seq as hospitalSeq, ch.name as hospitalName, CASE WHEN EXISTS ( SELECT 1 FROM account_disease ad WHERE ad.service_seq = hs.seq AND ad.is_enabled ) THEN 'APPROVE' ELSE 'REQUEST' END as status, ( SELECT to_char(min(ad.created_at) at time zone 'kst', 'YYYY-MM-DD HH24:MI:SS') FROM account_disease ad WHERE ad.service_seq = hs.seq AND ad.is_enabled ) as approveDate, to_char(cast(hs.created_at at time zone 'kst' AS timestamp), 'YYYY-MM-DD HH24:MI:SS') as createdAt from hospital_service hs join cm_hospital ch on ch.seq = hs.hospital_seq and ch.is_enabled join account ac on ac.seq = hs.account_seq and ac.is_enabled
hs.is_enabled AND hs.seq = #{seq}
AND hs.hospital_seq = #{hospitalSeq}
